﻿[package]
name = "independent-doc-print-review"
version = "0.0.0"
edition = "2024"
[workspace]
[dependencies]
nepl3-core = { path = "C:/projects/NEPL3-prefix-validation/crates/foundation/core" }
nepl3-reader = { path = "C:/projects/NEPL3-prefix-validation/crates/foundation/reader" }
nepl3-engine = { path = "C:/projects/NEPL3-prefix-validation/crates/foundation/engine" }
nepl3-wire = { path = "C:/projects/NEPL3-prefix-validation/crates/foundation/wire" }
nepl3-grammar-core = { path = "C:/projects/NEPL3-prefix-validation/crates/languages/grammar/core" }
nepl3-tools = { path = "C:/projects/NEPL3-prefix-validation/tools" }
nepl3-doc-core = { path = "C:/projects/NEPL3-prefix-validation/crates/languages/doc/core" }

include!("../helpers.rs");
use nepl3_doc_core::{check::Category,lower,model::*,print::{self,PrintRequest,PrintMode,PrintOutcome,PrintFailure,PrintMismatch}};
use nepl3_core::value_codec::FoundationValueCodec;
fn signature(b:&nepl3_core::syntax::SyntaxBundle)->Vec<(String,Option<NdfValue>)>{b.nodes.iter().map(|n|(n.kind.clone(),n.token.map(|t|b.tokens[t.0 as usize].payload.clone()))).collect()}
fn host(doc:&DocumentSyntax,profile:&ResolvedParseProfile<'_>)->Result<PrintRequest,String>{
 let empty=SourceStore::default();let mut a=SourceAdmission::default();let mut c=FoundationCodec::new(profile.registry(),&empty,&mut a).map_err(err)?;
 let identity=print::identity(doc,profile.registry(),&mut c,&mut budget()).map_err(err)?;
 let dv=nepl3_doc_core::portable::to_value(doc,profile.registry(),&mut c,&mut budget()).map_err(err)?;
 let mut domain=b"NEPL3.Doc.Print.Document.v1\0".to_vec();domain.extend(nepl3_wire::encode(&dv,&mut budget()).map_err(err)?);assert_eq!(Digest::of(&domain),identity.document_digest);
 let mut bindings=Vec::new();let mut guests=Vec::new();
 for target in &identity.guests {
  let e=&doc.value.embeds[target.embed.0 as usize];
  let (alias,category,language)=[("Math","Expr",GuestLanguage::Math),("Circuit","Design",GuestLanguage::Circuit),("Grammar","Root",GuestLanguage::Grammar),("Doc","Article",GuestLanguage::Doc)].into_iter().find(|(alias,_,_)|profile.language(alias,&mut budget()).is_ok_and(|p|p.schema==e.closure.syntax.schema)).ok_or("selected guest")?;
  if !bindings.iter().any(|v:&print::GuestBinding|v.language==language){bindings.push(print::GuestBinding{schema:e.closure.syntax.schema.clone(),category:category.into(),language});}
  let v=c.encode_foreign_closure(&e.closure,&mut budget()).map_err(err)?;let mut bytes=b"NEPL3.Doc.Print.Guest.v1\0".to_vec();bytes.extend(nepl3_wire::encode(&v,&mut budget()).map_err(err)?);assert_eq!(Digest::of(&bytes),target.guest_digest);
  let raw=print::original_guest_source(doc,target.embed,profile.registry(),&mut budget(),&mut SourceAdmission::default()).map_err(err)?.ok_or("guest raw")?;
  let source=SourceSnapshot::new(SourceId(format!("independent-guest-{}",target.embed.0)),0,format!("memory:independent-guest/{}",target.embed.0),raw.as_bytes().to_vec(),&mut budget()).map_err(err)?;
  let mut b=budget();let mut ad=SourceAdmission::default();let parsed=parse_source_as(&source,profile,alias,category,&mut b,&mut ad)?;assert_eq!(signature(&parsed.bundle),signature(&e.closure.syntax.bundle));
  let proof=parsed.validate(profile,&mut b,&mut ad).map_err(err)?;let output=nepl3_engine::parse::print::source_tree(&proof,&mut b,&mut ad).map_err(err)?;
  let nepl3_engine::parse::print::PrintOutcome::Complete(text)=output.outcome else{return Err("guest stopped".into())};
  guests.push(print::PrintedGuest{document_digest:identity.document_digest,embed:target.embed,guest_digest:target.guest_digest,text});
 }
 Ok(PrintRequest{document:doc.clone(),mode:PrintMode::Prefix,bindings,guests})
}
fn raw_run(request:&PrintRequest,r:&nepl3_core::schema::SchemaRegistry)->Result<PrintOutcome,String>{let empty=SourceStore::default();let mut a=SourceAdmission::default();let mut c=FoundationCodec::new(r,&empty,&mut a).map_err(err)?;let v=nepl3_doc_core::portable::print::request_to_value(request,r,&mut c,&mut budget()).map_err(err)?;let bytes=nepl3_wire::encode(&v,&mut budget()).map_err(err)?;drop(c);let receiver_empty=SourceStore::default();let mut ra=SourceAdmission::default();let mut rc=FoundationCodec::new(r,&receiver_empty,&mut ra).map_err(err)?;let v=nepl3_wire::decode(&bytes,&mut budget()).map_err(err)?;let rr=nepl3_doc_core::portable::print::request_from_value(&v,r,&mut rc,&mut budget()).map_err(err)?;Ok(print::print(&rr,r,&mut rc,&mut budget()).map_err(err)?.outcome)}
fn main()->Result<(),String>{let compiled=compiled()?;
 for (text,entry,category) in [
  ("sentence cons math Math add 1 2 cons text \"tail\" nil","Sentence",Category::Sentence),
  ("Math mul 2 3","MathGuest",Category::MathGuest),
  ("Circuit design nil Main nil","CircuitGuest",Category::CircuitGuest),
  ("Grammar language Tiny 1 Expr nil","Guest",Category::Guest),
  ("Doc article en sentence cons anno text \"\" cons text \"note\" nil nil body nil","Guest",Category::Guest),
 ] {with_input(&compiled,text,entry,|tree,profile,b,a|{
  let checked=tree.tree().bundle.validate_with_sources(profile.registry(),b,a).map_err(err)?;let empty=SourceStore::default();let mut ca=SourceAdmission::default();let mut c=FoundationCodec::new(profile.registry(),&empty,&mut ca).map_err(err)?;
  let doc=lower::document(&checked,&compiled.doc.package.schema,category,profile.registry(),b,&mut c).map_err(err)?;
  let request=host(&doc,profile)?;
  for mode in [PrintMode::Prefix,PrintMode::Compact]{let mut request=request.clone();request.mode=mode;let PrintOutcome::Complete{artifact}=raw_run(&request,profile.registry())? else{return Err("good guest".into())};
   let source=SourceSnapshot::new(SourceId("independent-reprint".into()),0,"memory:independent-reprint".into(),artifact.text.as_bytes().to_vec(),&mut budget()).map_err(err)?;
   let parsed=parse_source(&source,profile,entry,&mut budget(),&mut SourceAdmission::default())?;
   let checked=parsed.bundle.validate_with_sources(profile.registry(),&mut budget(),&mut SourceAdmission::default()).map_err(err)?;
   let actual=lower::document(&checked,&compiled.doc.package.schema,category,profile.registry(),&mut budget(),&mut c).map_err(err)?;
   assert_eq!(actual.value.root,doc.value.root);assert_eq!(actual.value.embeds.len(),doc.value.embeds.len());for (a,e) in actual.value.embeds.iter().zip(&doc.value.embeds){assert_eq!(signature(&a.closure.syntax.bundle),signature(&e.closure.syntax.bundle));}
  }
  let mut wrong=request.clone();wrong.guests[0].guest_digest=Digest::of(b"wrong");assert!(matches!(raw_run(&wrong,profile.registry())?,PrintOutcome::Invalid{error:PrintFailure::InvalidGuest{reason:PrintMismatch::Guest,..}}));
  let mut wrong=request.clone();wrong.guests[0].embed=EmbedRef((1u64<<32)+request.guests[0].embed.0);assert!(matches!(raw_run(&wrong,profile.registry())?,PrintOutcome::Invalid{error:PrintFailure::InvalidGuest{reason:PrintMismatch::Embed,..}}));
  if entry=="Sentence" {
