// Actual standard Doc source compilation and prefix parsing. Facts signatures
// are compile-time declarations only; this parse-only host serves reader calls.
use nepl3_core::{budget::*, source::*};
use nepl3_core::{
    syntax::{Environment, EnvironmentEntry},
    value::NdfValue,
};
use nepl3_engine::{parse::*, profile::*, tree::ValidatedParseTree};
use nepl3_grammar_core::compile::package::CompiledLanguage;
use nepl3_reader::{
    model::{ProviderCall, ReadRequest, ReaderContext},
    runtime::ProviderReply,
};
use nepl3_wire::{environment::environment_digest, foundation::FoundationCodec};
fn err(v: impl std::fmt::Debug) -> String {
    format!("{v:?}")
}
fn with_input<T>(
    compiled: &Compiled,
    input: &str,
    category: &str,
    finish: impl FnOnce(
        &ValidatedParseTree<'_>,
        &ResolvedParseProfile<'_>,
        &mut Budget,
        &mut SourceAdmission,
    ) -> Result<T, String>,
) -> Result<T, String> {
    let r = &compiled.doc.registry;
    let packages: Vec<_> = std::iter::once(&compiled.doc.package)
        .chain(compiled.others.iter())
        .collect();
    // Each runtime registration identifies the actual source serving that operation.
    let implementation_for = |operation: &nepl3_core::value::OperationRef| {
        if operation.schema.package == "nepl3.doc.reader" {
            Digest::of(include_bytes!("C:/projects/NEPL3-prefix-validation/tools/src/doc/reader.rs"))
        } else {
            Digest::of(include_bytes!("C:/projects/NEPL3-prefix-validation/crates/foundation/reader/src/builtin/provider.rs"))
        }
    };
    let mut operations = Vec::new();
    for operation in packages
        .iter()
        .flat_map(|p| p.reader.providers.iter().map(|v| &v.operation))
    {
        if !operations.contains(operation) {
            operations.push(operation.clone());
        }
    }
    let providers: Vec<_> = operations
        .iter()
        .map(|operation| ProviderImplementation {
            provider: operation.name.clone(),
            revision: 1,
            implementation_digest: implementation_for(operation),
            operations: vec![operation.clone()],
        })
        .collect();
    let requirements = operations
        .iter()
        .map(|operation| ProviderRequirement {
            provider: operation.name.clone(),
            revision: 1,
            implementation_digest: implementation_for(operation),
            operation: operation.clone(),
        })
        .collect();
    let mut schemas = packages
        .iter()
        .map(|p| p.schema.clone())
        .collect::<Vec<_>>();
    for schema in packages
        .iter()
        .flat_map(|p| p.payload_schemas.iter())
        .chain(
            [
                "nepl3.foundation",
                "nepl3.reader",
                "nepl3.engine",
                "nepl3.doc",
                "nepl3.doc.reader",
                "nepl3.grammar",
            ]
            .iter()
            .filter_map(|name| r.selected(name, 1)),
        )
    {
        if !schemas.contains(schema) {
            schemas.push(schema.clone());
        }
    }
    let profile = ParseProfile {
        id: "doc-prefix".into(),
        languages: packages
            .iter()
            .zip([
                ("Doc", "Article"),
                ("Math", "Expr"),
                ("Circuit", "Design"),
                ("Grammar", "Root"),
            ])
            .map(|(p, (alias, category))| {
                Ok(LanguageRegistration {
                    alias: alias.into(),
                    package: p
                        .check(r, &mut budget())
                        .and_then(|c| c.semantic_identity(&mut budget()))
                        .map_err(err)?,
                    default_category: category.into(),
                })
            })
            .collect::<Result<Vec<_>, String>>()?,
        schemas,
        head_providers: vec![],
        category_modes: vec![],
        providers: requirements,
        allowlist: operations,
        resources: vec![],
        limits: budget().limits(),
    };
    let resolved = profile
        .resolve(
            &RuntimeCatalog {
                packages: &packages,
                providers: &providers,
                resources: &[],
            },
            r,
            &mut budget(),
        )
        .map_err(err)?;
    let mut b = budget();
    let mut a = SourceAdmission::default();
    let source = SourceSnapshot::new(
        SourceId("doc-input".into()),
        0,
        "memory:doc-input".into(),
        input.as_bytes().to_vec(),
        &mut b,
    )
    .map_err(err)?;
    let tree = parse_source(&source, &resolved, category, &mut b, &mut a)?;
    let checked = tree.validate(&resolved, &mut b, &mut a).map_err(err)?;
    finish(&checked, &resolved, &mut b, &mut a)
}

fn parse_source_as(
    source: &SourceSnapshot,
    resolved: &ResolvedParseProfile<'_>,
    alias: &str,
    category: &str,
    b: &mut Budget,
    a: &mut SourceAdmission,
) -> Result<nepl3_engine::recovery::ParseTree, String> {
    let r = resolved.registry();
    let foundation = r.selected("nepl3.foundation", 1).ok_or("foundation")?;
    let mut store = SourceStore::default();
    store.insert(source.clone()).map_err(err)?;
    let value = Environment {
        bindings: vec![],
        resources: vec![],
    };
    let digest = environment_digest(&value, foundation, r, b).map_err(err)?;
    let mut contexts = Vec::new();
    for (alias, category) in [
        ("Doc", "Article"),
        ("Math", "Expr"),
        ("Circuit", "Design"),
        ("Grammar", "Root"),
    ] {
        let owner = resolved.language(alias, b).map_err(err)?;
        contexts.push(ReaderContext {
            schema: owner.schema.clone(),
            category: category.into(),
            mode: "Code".into(),
            origins: vec![],
            environment: EnvironmentEntry {
                id: 0,
                digest,
                value: value.clone(),
            },
        });
    }
    let environments = {
        let mut codec = FoundationCodec::new(r, &store, a).map_err(err)?;
        let checked = contexts
            .iter()
            .map(|raw| raw.check(&mut codec, &store, r, b).map_err(err))
            .collect::<Result<Vec<_>, String>>()?;
        let inputs = checked
            .iter()
            .zip(["Doc", "Math", "Circuit", "Grammar"])
            .map(|(context, alias)| EnvironmentInput { alias, context })
            .collect::<Vec<_>>();
        ParseEnvironmentSet::prepare(resolved, &inputs, &store, &mut codec, b)
            .map_err(|e| format!("environments: {e:?}"))?
    };
    let entry = resolved.entry(alias, Some(category), b).map_err(err)?;
    let states = ["Doc", "Math", "Circuit", "Grammar"].map(|alias| LanguageReaderState {
        alias: alias.into(),
        state: NdfValue::Unit,
    });
    let mut parser =
        ParseSession::new("doc-parse".into(), resolved, &environments, b).map_err(err)?;
    let mut result = parser
        .read(
            ParseRequest {
                snapshot: source,
                start: 0,
                limit: source.text().len() as u64,
                final_input: true,
                entry: &entry,
                states: &states,
            },
            &store,
            b,
            a,
        )
        .map_err(err)?;
    let mut reservations = 0;
    loop {
        match result.outcome {
            ParseOutcome::Await { call, continuation } => {
                let ProviderCall::Read {
                    operation,
                    request,
                    depth_base,
                    ..
                } = call.as_ref()
                else {
                    return Err("unexpected provider".into());
                };
                let mut declared = SourceStore::default();
                for source in &request.sources {
                    declared.insert(source.clone()).map_err(err)?;
                }
                let snapshot = declared
                    .resolve(&request.snapshot)
                    .ok_or("request source")?;
                let terminal = b
                    .with_depth_at_least(*depth_base, |b| {
                        let mut codec = FoundationCodec::new(r, &declared, a)
                            .map_err(|_| nepl3_reader::runtime::ReaderError::Context)?;
                        let checked = request
                            .context
                            .check(&mut codec, &declared, r, b)
                            .map_err(|_| nepl3_reader::runtime::ReaderError::Context)?;
                        (if operation.schema.package == "nepl3.doc.reader" {
                            nepl3_tools::doc::reader::read
                        } else {
                            nepl3_reader::builtin::provider::read
                        })(
                            operation,
                            ReadRequest {
                                snapshot,
                                start: request.start,
                                limit: request.limit,
                                final_input: request.final_input,
                                context: &checked,
                                state: &request.state,
                            },
                            r,
                            &declared,
                            b,
                            a,
                        )
                    })
                    .map_err(err)?;
                result = parser
                    .resume(
                        &continuation,
                        ProviderReply::Read(Box::new(terminal)),
                        &store,
                        b,
                        a,
                    )
                    .map_err(err)?;
            }
            ParseOutcome::Reserve { continuation, .. } => {
                reservations += 1;
                let reserved = SourceReservation {
                    source_id: SourceId(format!("decoded-{reservations}")),
                    revision: 0,
                    uri: format!("memory:decoded-{reservations}"),
                };
                result = parser
                    .reserve(&continuation, &reserved, &store, b, a)
                    .map_err(err)?;
            }
            ParseOutcome::Complete { tree, cursor, .. } => {
                assert_eq!(cursor, source.text().len() as u64);
                return Ok(tree);
            }
            other => return Err(format!("candidate: {other:?}")),
        }
    }
}

fn budget() -> Budget {
    Budget::new(Limits {
        source_bytes: 10_000_000,
        work: 100_000_000,
        depth: 1000,
        nodes: 1_000_000,
        allocation_units: 500_000_000,
        output_bytes: 10_000_000,
        diagnostics: 1000,
        events: 1000,
    })
}
struct Compiled {
    doc: CompiledLanguage,
    others: Vec<nepl3_engine::package::LanguagePackage>,
}
fn compiled() -> Result<Compiled, String> {
    let document = nepl3_tools::bootstrap::load(
        include_bytes!("C:/projects/NEPL3-prefix-validation/conformance/fixtures/doc/syntax.json"),
        &mut budget(),
        &mut SourceAdmission::default(),
    )
    .map_err(err)?;
    let mut doc = nepl3_tools::doc::catalog::compile(
        &document,
        "standard.doc",
        &mut budget(),
        &mut SourceAdmission::default(),
    )?;
    let mut others = Vec::new();
    for (name, seed) in [
        (
            "math",
            include_bytes!("C:/projects/NEPL3-prefix-validation/conformance/fixtures/doc/math.json").as_slice(),
        ),
        (
            "circuit",
            include_bytes!("C:/projects/NEPL3-prefix-validation/conformance/fixtures/doc/circuit.json").as_slice(),
        ),
        (
            "grammar",
            include_bytes!("C:/projects/NEPL3-prefix-validation/conformance/fixtures/doc/grammar.json").as_slice(),
        ),
    ] {
        let document =
            nepl3_tools::bootstrap::load(seed, &mut budget(), &mut SourceAdmission::default())
                .map_err(err)?;
        let other = nepl3_tools::doc::catalog::compile(
            &document,
            &format!("standard.{name}"),
            &mut budget(),
            &mut SourceAdmission::default(),
        )?;
        let schema = other.package.schema.clone();
        let descriptor = other
            .registry
            .descriptor(&schema)
            .ok_or("surface descriptor")?
            .clone();
        doc.registry
            .register(schema, descriptor, &mut budget())
            .map_err(err)?;
        others.push(other.package);
    }
    doc.registry.finalize(&mut budget()).map_err(err)?;
    Ok(Compiled { doc, others })
}



fn parse_source(source:&SourceSnapshot,resolved:&ResolvedParseProfile<'_>,category:&str,b:&mut Budget,a:&mut SourceAdmission)->Result<nepl3_engine::recovery::ParseTree,String>{parse_source_as(source,resolved,"Doc",category,b,a)}

include!("helpers.rs");
use nepl3_doc_core::{check::Category,lower,model::*,print::{self,PrintRequest,PrintMode,PrintOutcome}};
fn category(s:&str)->Category{match s{"Block"=>Category::Block,"Inline"=>Category::Inline,"Flow"=>Category::Flow,"OptionalText"=>Category::OptionalText,_=>Category::Sentence}}
fn document(compiled:&Compiled,input:&str,entry:&str)->Result<DocumentSyntax,String>{with_input(compiled,input,entry,|tree,profile,b,a|{let checked=tree.tree().bundle.validate_with_sources(profile.registry(),b,a).map_err(err)?;let empty=SourceStore::default();let mut codec=FoundationCodec::new(profile.registry(),&empty,a).map_err(err)?;lower::document(&checked,&compiled.doc.package.schema,category(entry),profile.registry(),b,&mut codec).map_err(err)})}
fn main()->Result<(),String>{
 let compiled=compiled()?;let r=&compiled.doc.registry;
 for (id,entry,text) in [("empty","Sentence","sentence nil"),
("escaped","Sentence","sentence cons text \"[字]/{}\\\\\\\"\\r\\n\\t\" nil"),
("nested","Sentence","sentence cons ruby text \"基\" anno text \"読\" cons text \"注\" nil nil"),
("fallback","Sentence","sentence cons text \"a\" cons break cons strong text \"b\" nil"),
("inline-root","Inline","ruby text \"x\" text \"y\""),
("flow-root","Flow","sentence cons text \"x\" nil"),
("raw","Block","rawcode some \"rust\" \"[x]\\n{}\""),
("helper-empty","OptionalText","some \"\""),
("name-reserved","Block","section section sentence nil body nil")] {
  let doc=document(&compiled,text,entry)?;
  for mode in [PrintMode::Prefix,PrintMode::Compact]{
   let request=PrintRequest{document:doc.clone(),mode,bindings:vec![],guests:vec![]};
   let empty=SourceStore::default();let mut a=SourceAdmission::default();let mut c=FoundationCodec::new(r,&empty,&mut a).map_err(err)?;
   let mut b=budget();let reply=print::print(&request,r,&mut c,&mut b).map_err(err)?;
   let PrintOutcome::Complete{artifact}=&reply.outcome else{return Err(format!("{id}: {reply:?}"))};
   let actual=document(&compiled,&artifact.text,entry)?;
   assert_eq!(actual.value.root,doc.value.root,"{id}");
   assert_eq!(actual.value.nodes.iter().map(|n|&n.kind).collect::<Vec<_>>(),doc.value.nodes.iter().map(|n|&n.kind).collect::<Vec<_>>(),"{id}: {}",artifact.text);
   if id=="empty" && mode==PrintMode::Compact {assert_eq!(artifact.text,"\"\"");}
   if id=="fallback" {assert!(artifact.text.contains("break"));assert!(artifact.text.contains("strong"));}
   let v=nepl3_doc_core::portable::print::request_to_value(&request,r,&mut c,&mut budget()).map_err(err)?;
   let bytes=nepl3_wire::encode(&v,&mut budget()).map_err(err)?;
   drop(request);drop(c);
   let re=SourceStore::default();let mut ra=SourceAdmission::default();let mut rc=FoundationCodec::new(r,&re,&mut ra).map_err(err)?;
   let decoded=nepl3_wire::decode(&bytes,&mut budget()).map_err(err)?;
   let received=nepl3_doc_core::portable::print::request_from_value(&decoded,r,&mut rc,&mut budget()).map_err(err)?;
   let rr=print::print(&received,r,&mut rc,&mut budget()).map_err(err)?;
   assert_eq!(rr.outcome,reply.outcome);
   let rv=nepl3_doc_core::portable::print::reply_to_value(&rr,&received.document,r,&mut rc,&mut budget()).map_err(err)?;
   let rb=nepl3_wire::encode(&rv,&mut budget()).map_err(err)?;
   let rv=nepl3_wire::decode(&rb,&mut budget()).map_err(err)?;
   assert_eq!(nepl3_doc_core::portable::print::reply_from_value(&rv,&received.document,r,&mut rc,&mut budget()).map_err(err)?,rr);
   println!("original {id}/{mode:?}: actual parse/lower, entry {entry}, initial CBOR print and reply Eq");
  }
 }
 Ok(())
}
